if(type==='buyEchoes'){if(!Number.isInteger(i.count)||i.count<1||i.count>10)throw Error('Оберіть від 1 до 10 відлунь');if(!ZONES[this.s.zone].objects.some(o=>o.kind==='merchant'&&dist(h,o)<3))throw Error('Підійдіть до торговця для обміну');let price=ECHO_PRICE*i.count;if(h.zeny<price)throw Error('Бракує Zeny для обміну');h.zeny-=price;h.echoes=(h.echoes||0)+i.count;this.event('trade',{actor:h.id,text:`Обмін: −${price} Z · +${i.count} Відлуння душ`});return{}}
